HTTP/1.1 401
Content-Type: text/html;charset=utf-8

<!doctype html><html lang="en"><head><title>HTTP Status 401</title>

#   HTML 이 나온다

#   JSON 을 기대한 클라이언트가 파싱에 실패한다

# --- 직접 쓴다 ---

@Component
@RequiredArgsConstructor
public class ProblemWriter {
    private final ObjectMapper objectMapper;

    public void write(HttpServletRequest req, HttpServletResponse res,
            HttpStatus status, String detail) throws IOException {
        ProblemDetail body = ProblemDetail.forStatusAndDetail(status, detail);
        body.setInstance(URI.create(req.getRequestURI()));
        res.setStatus(status.value());
        res.setContentType("application/problem+json");
        objectMapper.writeValue(res.getWriter(), body);
    }
}

http.exceptionHandling(e -> e
        .authenticationEntryPoint((req, res, ex) ->
                writer.write(req, res, UNAUTHORIZED, "authentication required"))
        .accessDeniedHandler((req, res, ex) ->
                writer.write(req, res, FORBIDDEN, "forbidden")));

$ curl -i localhost:8080/api/v1/orders

HTTP/1.1 401
Content-Type: application/problem+json

{"type":"about:blank","title":"Unauthorized","status":401,
 "detail":"authentication required","instance":"/api/v1/orders"}

$ curl -i -u user@a.com:1234 localhost:8080/api/v1/admin/orders

HTTP/1.1 403
Content-Type: application/problem+json

{"type":"about:blank","title":"Forbidden","status":403,
 "detail":"forbidden","instance":"/api/v1/admin/orders"}

#   둘이 같은 모양이다

# --- 메서드 보안 쪽도 맞춘다 ---

@RestControllerAdvice
public class ApiExceptionHandler {
    @ExceptionHandler(AccessDeniedException.class)
    ProblemDetail denied(HttpServletRequest req) {
        ProblemDetail body = ProblemDetail.forStatusAndDetail(
                HttpStatus.FORBIDDEN, "forbidden");
        body.setInstance(URI.create(req.getRequestURI()));
        return body;
    }
}

